using System;

namespace PeroTools2.Error;

/// <summary>
/// Used on an error enum field to declare the default message template of its companion error
/// class.<br/>
/// An error enum field carrying this attribute gets a companion error class generated by
/// <c>PeroTools2.PeroError.Generator</c>.<br/>
/// </summary>
/// <remarks>
/// <para>
/// The format string uses C# interpolated string syntax, for example
/// <c>"File {path} Do Not Exist"</c>:
/// </para>
/// <list type="bullet">
/// <item>
/// A placeholder such as <c>{name}</c> must match a parameter name declared by
/// <see cref="ErrArgAttribute"/>, otherwise it is a compile error
/// </item>
/// <item>
/// Placeholders support alignment and format specifiers, for example
/// <c>{retryCount,5}</c> / <c>{line:X4}</c>
/// </item>
/// <item>Literal braces are escaped as <c>{{</c> and <c>}}</c></item>
/// </list>
/// </remarks>
/// <example>
/// <code>
/// public enum IOErr
/// {
///     [ErrMsg("File {path} Do Not Exist")]
///     [ErrArg("path", typeof(string), "Path that was not found")]
///     NotFound,
/// }
///
/// // The above automatically generates IOErr_NotFound : Err&lt;IOErr&gt;
/// var err = new IOErr_NotFound("a.txt");
/// </code>
/// </example>
[AttributeUsage(AttributeTargets.Field, AllowMultiple = false, Inherited = false)]
public sealed class ErrMsgAttribute : Attribute
{
    /// <summary>Default message template (interpolated string syntax)</summary>
    public string format { get; }

    /// <summary>
    /// Custom name for the generated companion class.<br/>
    /// Defaults to <c>{error enum name}_{error enum field name}</c>.
    /// (Used by the generator only)
    /// </summary>
    public string? name { get; set; }

    /// <summary>Declares the default message template</summary>
    /// <param name="format">Default message template (interpolated string syntax)</param>
    public ErrMsgAttribute(string format) => this.format = format;
}